"""Visual skin layered over the shell in views.page().

Presentation only: extra CSS/JS and decorative chrome. No routes, permissions or data
are decided here; `may` is passed in so navigation mirrors what the top bar already shows.
Animations are on by default and controlled only by the in-app toggle (localStorage
"fr-motion"); the OS reduce-motion setting is intentionally not consulted.
"""
from __future__ import annotations

from collections.abc import Callable

_MOTION_BOOT = (
    '<script>try{if(localStorage.getItem("fr-motion")==="off")'
    'document.documentElement.classList.add("motion-off")}catch(e){}</script>'
)

CSS = '/* ===== shared skin layer: calm palette, glow buttons, no thin borders ===== */\n:root{--fw1:#5C7F99;--fw2:#7E9A7A;--fw3:#B59A6A;--sage:#7E9A7A;--green:#3F7D62;\n  --g-blue:var(--fw1);--g-green:var(--fw2);--g-yellow:var(--fw3);--g-red:#B5706A;\n  --g-rainbow:linear-gradient(90deg,var(--fw1),var(--fw2),var(--fw3));\n  --gemini-gradient:linear-gradient(110deg,var(--accent) 0%,var(--sage) 55%,var(--fw3) 100%);\n  --ease:cubic-bezier(.2,.7,.2,1)}\n:root[data-theme="light"]{\n  --ground:#EEF2F1;--surface:#FFFFFF;--surface-high:#F5F8F7;--surface-highest:#E9EFED;\n  --sunk:#E7EDEB;--ink:#1F2A30;--body:#3A4750;--muted:#66767F;--rule:#DFE6E4;\n  --accent:#5C7F99;--accent-strong:#4A6B84;--accent-soft:#E2EBF0;--ask:#A65E57;\n  --success:#3F7D62;--success-soft:#E1EEE6;\n  --topbar-bg:rgba(238,242,241,.82);--topbar-line:transparent;--topglow:rgba(92,127,153,.14);\n  --row-hover:rgba(92,127,153,.05);--card-hover:#fff;--card-hover-line:transparent;\n  --selection:rgba(92,127,153,.25);\n  --card-shadow:0 1px 2px rgba(31,42,48,.04),0 6px 22px rgba(31,42,48,.06);\n  --card-shadow-hover:0 4px 10px rgba(31,42,48,.06),0 22px 48px rgba(63,90,110,.16);\n  --glow:rgba(92,127,153,.38)}\n:root:not([data-theme="light"]){\n  --ground:#1B1F23;--surface:#22272C;--surface-high:#2A3036;--surface-highest:#323940;\n  --sunk:#181B1F;--ink:#E9EDEB;--body:#C4CCC9;--muted:#8D9A97;--rule:#2E353B;\n  --accent:#8FB0C6;--accent-strong:#5C7F99;--accent-soft:#2A3843;--ask:#D7958D;\n  --success:#7DBA98;--success-soft:#21332A;\n  --fw1:#8FB0C6;--fw2:#9DB89A;--fw3:#CDB487;--sage:#9DB89A;\n  --topbar-bg:rgba(27,31,35,.82);--topbar-line:transparent;--topglow:rgba(143,176,198,.12);\n  --row-hover:rgba(255,255,255,.025);--card-hover:#262C32;--card-hover-line:transparent;\n  --selection:rgba(143,176,198,.3);\n  --card-shadow:0 1px 2px rgba(0,0,0,.25),0 10px 28px rgba(0,0,0,.28);\n  --card-shadow-hover:0 6px 14px rgba(0,0,0,.3),0 26px 60px rgba(0,0,0,.42);\n  --glow:rgba(63,125,98,.45)}\nbody{font-size:16.5px}\n.wrap,.wrap.wide{max-width:1760px;padding:0 clamp(1.25rem,2.6vw,3rem) 5rem}\n.top,.wrap.wide .top{padding:.85rem clamp(1.25rem,2.6vw,3rem);border-bottom:0}\n.top::after{display:none}\n.gemini-sparkle{color:var(--fw3)}\n/* no thin borders anywhere on boxes */\n.card,.stat-card,.hud-card,table,form,.empty-gap,form.seek,.chip,.callout,.mark,.tag,\n.keynote-pill,.stage-eyebrow,.signed,.draft,.shuffle-btn,.themebtn,textarea,\ninput[type=text],input[type=password],input[type=file],input[type=search],select{border-color:transparent!important}\nform.tiny{box-shadow:none;background:transparent}\n.card::after{display:none}\n.card::before{background:radial-gradient(28rem circle at var(--mx,50%) var(--my,50%),\n  color-mix(in srgb,var(--accent) 16%,transparent),transparent 62%)}\n/* left accent bars -> soft tinted blocks */\n.daily-card .snippet,.doc p.own{border-left:0!important;border-radius:12px!important;padding:.7rem .95rem!important}\n.err{border-left:0;border-radius:14px;background:color-mix(in srgb,var(--ask) 12%,var(--surface))}\n.aurora i:nth-child(1){background:radial-gradient(circle,var(--fw1),transparent 65%)}\n.aurora i:nth-child(2){background:radial-gradient(circle,var(--fw2),transparent 65%)}\n.aurora i:nth-child(3){background:radial-gradient(circle,var(--green),transparent 65%)}\n.aurora i:nth-child(4){background:radial-gradient(circle,var(--fw3),transparent 65%)}\n.aurora i{opacity:.14}:root[data-theme="light"] .aurora i{opacity:.16}\n/* buttons: glow + shine sweep, press 97%, keyboard-only focus ring */\nbutton,a.cta,form.seek button{border:0!important;color:#fff;font-weight:600;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 88%,#fff),var(--accent-strong));\n  box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -4px var(--glow);\n  transition:transform .18s var(--ease),box-shadow .25s var(--ease),filter .2s}\n:root:not([data-theme="light"]) button,:root:not([data-theme="light"]) a.cta,\n:root:not([data-theme="light"]) form.seek button{\n  background:linear-gradient(180deg,#4C8E70,var(--green))}\nbutton:hover,a.cta:hover,form.seek button:hover{opacity:1;filter:brightness(1.06);transform:translateY(-1px);\n  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 10px 28px -4px var(--glow),0 0 0 4px color-mix(in srgb,var(--glow) 35%,transparent)}\nbutton:active,a.cta:active{transform:scale(.97)}\nbutton:focus{outline:none}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\nbutton::after,a.cta::after{background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}\n.themebtn,.motionbtn,.shuffle-btn,form.tiny button.shuffle-btn{background:var(--surface-high)!important;color:var(--ink)!important;\n  box-shadow:var(--card-shadow)!important}\n.motionbtn{display:inline-flex;align-items:center;justify-content:center;padding:.45rem .6rem;border-radius:980px;margin-left:.2rem}\n.themebtn svg,.motionbtn svg{width:1.15rem;height:1.15rem;display:block}\n.motionbtn[aria-pressed="false"]{opacity:.55}\n.motionbtn[aria-pressed="true"] svg{color:var(--fw3)}\n/* inputs */\ntextarea,input[type=text],input[type=password],input[type=file]{background:var(--sunk);border-radius:12px}\ninput[type=password]{width:100%;padding:.65rem .85rem;font:inherit;color:var(--ink)}\nform.seek:focus-within{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 22%,transparent),0 14px 40px -8px var(--glow)}\n.chip{background:var(--surface-high);color:var(--body)}\n.chip:hover{background:var(--accent-soft);color:var(--ink)}\n.bar i,.hud-meter-fill{background:linear-gradient(90deg,var(--accent),var(--sage))}\ntable{border-collapse:separate}\ntd{border-bottom-color:color-mix(in srgb,var(--rule) 70%,transparent)}\n.tag.mine,.mark.mine{background:var(--success-soft);color:var(--success)}\n/* count-up + stagger */\n.stat-num{font-variant-numeric:tabular-nums}\n@keyframes skRise{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\n.sk-stagger>*{animation:skRise .7s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}\n/* control page: action cards without colored top bars, wider reading */\n.doing .claim::before,.doing .chat::before{display:none!important}\n.doing .claim,.doing .chat{border-color:transparent!important;border-radius:22px}\n.split{grid-template-columns:minmax(0,1fr) clamp(20rem,24vw,26rem);gap:clamp(1.5rem,3vw,3.5rem)}\n.doc p,.doc ul,.doc ol{max-width:86ch}\n.doing .claim button{border:0!important;color:#fff!important;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 85%,#fff),var(--accent-strong))!important}\n:root:not([data-theme="light"]) .doing .claim button{background:linear-gradient(180deg,#4C8E70,var(--green))!important}\n.graph-viewport{border-color:transparent!important;box-shadow:var(--card-shadow)}\n/* ===== C · Workbench (icon rail + ⌘K) ===== */\nbody:has(.sk-rail){padding-left:64px}\n.sk-rail{position:fixed;left:0;top:0;bottom:0;width:64px;z-index:200;display:flex;flex-direction:column;align-items:center;\n  padding:.8rem 0;gap:.4rem;background:var(--surface);box-shadow:1px 0 0 color-mix(in srgb,var(--ink) 6%,transparent),8px 0 30px -18px rgba(0,0,0,.35)}\n.sk-logo{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;margin-bottom:.8rem;\n  background:linear-gradient(150deg,var(--accent-strong),var(--green));box-shadow:0 8px 20px -6px var(--glow)}\n.sk-logo svg{width:30px;height:30px;fill:none;stroke:#fff;stroke-width:2.2;stroke-linejoin:round;stroke-linecap:round}\n.sk-lg path{animation:cStack 3.6s var(--ease) infinite}\n.sk-lg .p2{animation-delay:.15s}.sk-lg .p3{animation-delay:.3s}\n.sk-lg .p1{fill:rgba(255,255,255,.25)}\n@keyframes cStack{0%,100%{transform:none}40%{transform:translateY(-1.6px)}}\n.sk-rail-top,.sk-rail-bot{display:flex;flex-direction:column;gap:.35rem;align-items:center}\n.sk-rail-bot{margin-top:auto;padding-top:.8rem;gap:.5rem}\n.sk-ri{position:relative;width:44px;height:44px;border-radius:13px;display:grid;place-items:center;color:var(--muted);\n  transition:background .2s,color .2s,transform .18s var(--ease)}\n.sk-ri svg{width:22px;height:22px}\n.sk-ri:hover{background:var(--surface-high);color:var(--ink);text-decoration:none}\n.sk-ri.on{color:var(--ink);background:var(--accent-soft)}\n.sk-ri.on::before{content:"";position:absolute;inset:-3px;border-radius:15px;box-shadow:0 0 0 0 var(--glow);animation:cPulse 2.8s ease-out infinite}\n@keyframes cPulse{0%{box-shadow:0 0 0 0 var(--glow)}70%,100%{box-shadow:0 0 0 8px transparent}}\nbutton.sk-ri.sk-plain{padding:0;background:transparent;box-shadow:none;color:var(--muted)}\nbutton.sk-ri.sk-plain:hover{background:var(--surface-high);color:var(--ink);transform:none;box-shadow:none;filter:none}\nbutton.sk-ri.sk-plain::after{display:none}\n.sk-ri[data-sk-motion][aria-pressed="true"]{color:var(--fw3)}\n.sk-tip{position:absolute;left:56px;top:50%;transform:translate(-6px,-50%);white-space:nowrap;pointer-events:none;opacity:0;\n  font-size:.82rem;font-weight:600;padding:.35rem .7rem;border-radius:9px;background:var(--ink);color:var(--ground);transition:.18s var(--ease)}\n.sk-ri:hover .sk-tip{opacity:1;transform:translate(0,-50%)}\nbody:has(.sk-rail) .top .topnav,body:has(.sk-rail) .top .themebtn,body:has(.sk-rail) .top .motionbtn,body:has(.sk-rail) .top .who{display:none}\nbody:has(.sk-rail) .top{padding-top:.7rem!important;padding-bottom:.7rem!important;margin-bottom:1.4rem;width:auto;margin-left:calc(-1*clamp(1.25rem,2.6vw,3rem));margin-right:calc(-1*clamp(1.25rem,2.6vw,3rem));\n  background:color-mix(in srgb,var(--ground) 80%,transparent);box-shadow:0 1px 0 color-mix(in srgb,var(--ink) 6%,transparent)}\n.top h1{font-size:1.12rem}\n.crumb{font-size:.85rem;padding:.25rem .65rem;border-radius:8px;background:var(--surface-high)}\n.crumb:empty{display:none}\n.sk-k{margin-left:auto;display:inline-flex;align-items:center;gap:.7rem;min-width:22rem;padding:.6rem .8rem .6rem 1rem;border-radius:12px;\n  background:var(--surface)!important;color:var(--muted)!important;font-weight:500!important;box-shadow:var(--card-shadow)!important;justify-content:flex-start}\n.sk-k svg{width:18px;height:18px}.sk-k kbd{margin-left:auto;font:600 .72rem var(--mono);padding:.2rem .45rem;border-radius:6px;background:var(--sunk);color:var(--muted)}\n.sk-k:hover{color:var(--ink)!important;transform:none!important}\n/* palette */\n.sk-pal{position:fixed;inset:0;z-index:500;display:grid;justify-items:center;align-items:start;padding-top:14vh;\n  background:color-mix(in srgb,#0d1013 42%,transparent);backdrop-filter:blur(6px)}\n.sk-pal[hidden]{display:none}\n.sk-pal-box{width:min(42rem,92vw);border-radius:20px;background:var(--surface);box-shadow:0 40px 90px -20px rgba(0,0,0,.5);overflow:hidden;\n  animation:cPop .32s var(--ease) both}\n@keyframes cPop{from{opacity:0;transform:translateY(-10px) scale(.97)}}\n.sk-pal-in{display:flex;align-items:center;gap:.8rem;padding:1rem 1.2rem;background:var(--surface-high)}\n.sk-pal-in svg{width:22px;height:22px;color:var(--muted)}\n.sk-pal-in input{flex:1;border:0!important;background:transparent!important;font-size:1.1rem!important;box-shadow:none!important;padding:.3rem 0!important;outline:none}\n.sk-pal-in kbd{font:600 .72rem var(--mono);padding:.2rem .45rem;border-radius:6px;background:var(--sunk);color:var(--muted)}\n.sk-pal-list{max-height:52vh;overflow:auto;padding:.5rem}\n.sk-pal-g{font:600 .7rem var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);padding:.7rem .8rem .3rem}\n.sk-pal-it{display:flex;align-items:center;gap:.8rem;padding:.7rem .85rem;border-radius:12px;color:var(--ink);cursor:pointer;\n  animation:skRise .35s var(--ease) both;animation-delay:calc(var(--i,0)*25ms)}\n.sk-pal-it svg{width:20px;height:20px;color:var(--muted)}\n.sk-pal-it small{margin-left:auto;color:var(--muted);font-family:var(--mono)}\n.sk-pal-it.on{background:var(--accent-soft)}.sk-pal-it.on svg{color:var(--accent)}\n/* home: compact workbench header */\n.sk-hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:1.5rem;align-items:stretch;margin:0 0 1.5rem}\n.sk-hero>.sk-left{padding:2.2rem 2.4rem;border-radius:24px;background:var(--surface);box-shadow:var(--card-shadow);display:flex;flex-direction:column;justify-content:center}\n.sk-hero .stage-hero{text-align:left;margin:0 0 1.4rem}\n.sk-hero .stage-headline{font-size:clamp(2rem,3.2vw,3rem);line-height:1.1}\n.sk-hero .stage-sub{margin:0}\n.sk-hero form.seek{margin:0 0 .9rem;max-width:none;background:var(--sunk);box-shadow:none;border-radius:14px}\n.sk-hero form.seek button{border-radius:11px}\n.sk-hero .quick-chips{justify-content:flex-start;margin:.4rem 0}.sk-hero .note{text-align:left!important;margin:.4rem 0 0}\n.sk-visual{position:relative;min-height:440px;border-radius:24px;overflow:hidden;box-shadow:var(--card-shadow);\n  background:radial-gradient(90% 80% at 60% 45%,color-mix(in srgb,var(--green) 14%,var(--surface)),var(--surface) 75%)}\n.sk-visual canvas{position:absolute;inset:0;width:100%;height:100%}\n.sk-caption{position:absolute;left:1.3rem;top:1.1rem;font:600 .72rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.stage-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2rem;margin:0 0 2rem}\n.stat-card{text-align:left;padding:1.4rem 1.5rem;display:grid;grid-template-columns:auto 1fr;column-gap:1rem;align-items:center}\n.stat-num{grid-row:span 2;font-size:2.4rem;min-width:4.5ch}\n.stat-desc{margin:0;color:var(--ink)}.stat-sub{margin:0}\n.bento-layout{grid-template-columns:minmax(0,1fr) 380px;margin-top:1rem}\n.card{border-radius:18px}.card:hover{transform:translateY(-4px)}\n@media (max-width:1100px){.sk-hero{grid-template-columns:1fr}.stage-stats{grid-template-columns:repeat(2,1fr)}}\n.sk-login{display:grid;grid-template-columns:1.2fr 1fr;gap:3rem;align-items:center;min-height:calc(100vh - 9rem)}\n.sk-login .sk-visual{min-height:min(72vh,660px)}\n.sk-login .auth{max-width:30rem;width:100%;margin:0 auto}.sk-login .auth form{padding:2rem;border-radius:22px}\n.sk-login .auth h2{font-size:2rem;margin-top:0}\n'
