def _ic(name: str) -> str:
    return ('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" '
            f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{_ICON[name]}</svg>')


def chrome(*, bare: bool, may: Callable[[str], bool], who: str, title: str) -> str:
    if bare:
        return ""
    items = [("/", "home", "Home"), ("/frameworks", "frameworks", "Frameworks"),
             ("/graph", "graph", "Graph")]
    if may("framework:import"):
        items.append(("/import", "import", "Import framework"))
    if may("document:read"):
        items.append(("/documents", "documents", "Documents"))
    if may("member:read"):
        items.append(("/settings", "settings", "Settings"))
    links = "".join(
        f'<a class="sk-ri" href="{href}" data-sk-nav="{label}" aria-label="{label}">{_ic(icon)}'
        f'<span class="sk-tip">{label}</span></a>' for href, icon, label in items)
    bottom = (
        f'<button type="button" class="sk-ri sk-plain" data-sk-open aria-label="Command palette">{_ic("search")}'
        '<span class="sk-tip">Search · ⌘K</span></button>'
        f'<button type="button" class="sk-ri sk-plain" data-sk-theme aria-label="Toggle dark and light">{_ic("theme")}'
        '<span class="sk-tip">Theme</span></button>'
        f'<button type="button" class="sk-ri sk-plain" data-sk-motion aria-label="Toggle animations">{_ic("motion")}'
        '<span class="sk-tip">Animations</span></button>'
        + (f'<a class="sk-ri" href="/logout" aria-label="Sign out">{_ic("out")}'
           '<span class="sk-tip">Sign out</span></a>' if who else ""))
    return (
        '<nav class="sk-rail" aria-label="Workbench">'
        '<a class="sk-logo" href="/" aria-label="Framework Workbench">'
        '<svg viewBox="0 0 40 40" aria-hidden="true"><g class="sk-lg">'
        '<path class="p1" d="M8 13 20 7l12 6-12 6z"/><path class="p2" d="M8 20l12 6 12-6"/>'
        '<path class="p3" d="M8 27l12 6 12-6"/></g></svg></a>'
        f'<div class="sk-rail-top">{links}</div><div class="sk-rail-bot">{bottom}</div></nav>'
        '<div class="sk-pal" hidden><div class="sk-pal-box" role="dialog" aria-label="Command palette">'
        f'<div class="sk-pal-in">{_ic("search")}<input type="text" placeholder="Jump to a page, or search controls…" '
        'aria-label="Command"><kbd>Esc</kbd></div><div class="sk-pal-list" role="listbox"></div></div></div>'
    )


def tail() -> str:
    return (f"<style>{CSS}</style>" if CSS else "") + (
        f"<script>{TAIL_JS}</script>" if TAIL_JS else "")
